// SetEmf of the produtoTamanho to the related item.
// Sets o.R.Emf to related.
// Adds o to related.R.EmfProdutoTamanhos.
func (o *ProdutoTamanho) SetEmf(ctx context.Context, exec boil.ContextExecutor, insert bool, related *EmpresaFilial) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE `produto_tamanho` SET %s WHERE %s",
		strmangle.SetParamNames("`", "`", 0, []string{"emf_id"}),
		strmangle.WhereClause("`", "`", 0, produtoTamanhoPrimaryKeyColumns),
	)
	values := []interface{}{related.EmfID, o.PtamID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	o.EmfID = related.EmfID
	if o.R == nil {
		o.R = &produtoTamanhoR{
			Emf: related,
		}
	} else {
		o.R.Emf = related
	}

	if related.R == nil {
		related.R = &empresaFilialR{
			EmfProdutoTamanhos: ProdutoTamanhoSlice{o},
		}
	} else {
		related.R.EmfProdutoTamanhos = append(related.R.EmfProdutoTamanhos, o)
	}

	return nil
}

